questions.reference:
def standardize(values):
    if not values:
        return []
    n = len(values)
    m = sum(values) / n
    std = (sum((v - m) ** 2 for v in values) / n) ** 0.5
    if std == 0:
        return [0 for v in values]
    return [(v - m) / std for v in values]

