def precision(y_true, y_pred):
    tp = sum(1 for t, p in zip(y_true, y_pred) if p == 1 and t == 1)
    fp = sum(1 for t, p in zip(y_true, y_pred) if p == 1 and t == 0)
    if tp + fp == 0:
        return 0
    return tp / (tp + fp)

